import java.nio.file.*;import com.fasterxml.jackson.databind.*;import com.totaldocs.format.web.util.*;
public class PreflightProbe {public static void main(String[] args)throws Exception{var mapper=new ObjectMapper();var source=mapper.readTree(Path.of(args[0]).toFile());var layout=source.has("layout")?source.get("layout"):source;var report=LayoutPreflight.inspect(null,layout,LayoutPreflight.Policy.standard());Files.writeString(Path.of(args[1]),mapper.writerWithDefaultPrettyPrinter().writeValueAsString(report));System.out.println("Errors="+report.errors().size()+", warnings="+report.warnings().size()+", text fields="+report.measuredTexts());for(var e:report.errors())System.out.println(e.message());LayoutPreflight.requireValid(report,false);}}
